insert into public.site_settings (id, name, tagline, texts, phone, address, maps_url, lat, lng, socials, rating_google, rating_google_count, rating_google_url, google_review_url, rating_tripadvisor, rating_tripadvisor_count, rating_tripadvisor_url, theme, motion, timezone) values
  (1, 'Gelateria Onda', '{"it":"La Gelateria Artigianale","pl":"Rzemieślnicza lodziarnia","en":"The Artisan Gelateria","es":"La heladería artesanal","de":"Die handwerkliche Gelateria","fr":"Le glacier artisanal"}'::jsonb, '{"hero_title":{"it":"Onda","pl":"Onda","en":"Onda","es":"Onda","de":"Onda","fr":"Onda"},"hero_subtitle":{"it":"La Gelateria Artigianale · Santa Teresa Gallura","pl":"Rzemieślnicza lodziarnia · Santa Teresa Gallura","en":"The Artisan Gelateria · Santa Teresa Gallura","es":"La heladería artesanal · Santa Teresa Gallura","de":"Die handwerkliche Gelateria · Santa Teresa Gallura","fr":"Le glacier artisanal · Santa Teresa Gallura"},"cta_flavors":{"it":"I gusti di oggi","pl":"Dzisiejsze smaki","en":"Today''s flavors","es":"Sabores de hoy","de":"Sorten von heute","fr":"Les parfums du jour"},"cta_directions":{"it":"Come arrivare","pl":"Jak dojechać","en":"Get directions","es":"Cómo llegar","de":"Anfahrt","fr":"Itinéraire"},"flavors_title":{"it":"I gusti di oggi","pl":"Dzisiejsze smaki","en":"Today''s flavors","es":"Los sabores de hoy","de":"Die Sorten von heute","fr":"Les parfums du jour"},"flavors_subtitle":{"it":"Cambiano ogni giorno, come il mare.","pl":"Zmieniają się codziennie, jak morze.","en":"They change every day, like the sea.","es":"Cambian cada día, como el mar.","de":"Sie wechseln jeden Tag, wie das Meer.","fr":"Ils changent chaque jour, comme la mer."},"configurator_title":{"it":"Crea il tuo cono","pl":"Stwórz swój rożek","en":"Build your cone","es":"Crea tu cucurucho","de":"Stell dein Eis zusammen","fr":"Compose ton cornet"},"configurator_subtitle":{"it":"Scegli la misura, tocca i gusti, mostralo al banco.","pl":"Wybierz rozmiar, dotknij smaków, pokaż przy ladzie.","en":"Pick a size, tap your flavors, show it at the counter.","es":"Elige el tamaño, toca los sabores y enséñalo en el mostrador.","de":"Größe wählen, Sorten antippen, an der Theke zeigen.","fr":"Choisis la taille, touche tes parfums, montre-le au comptoir."},"signature_title":{"it":"Yellow Submarine","pl":"Yellow Submarine","en":"Yellow Submarine","es":"Yellow Submarine","de":"Yellow Submarine","fr":"Yellow Submarine"},"signature_body":{"it":"Il nostro gusto firma: ricotta, zafferano e pistacchio.","pl":"Nasz firmowy smak: ricotta, szafran i pistacja.","en":"Our signature flavor: ricotta, saffron and pistachio.","es":"Nuestro sabor estrella: ricotta, azafrán y pistacho.","de":"Unsere Signature-Sorte: Ricotta, Safran und Pistazie.","fr":"Notre parfum signature : ricotta, safran et pistache."},"lab_title":{"it":"Il Laboratorio","pl":"Pracownia","en":"The Workshop","es":"El obrador","de":"Die Werkstatt","fr":"L''atelier"},"lab_body":{"it":"Latte fresco, ingredienti sardi e tanta pazienza. Il nostro gelato nasce ogni giorno nel laboratorio, a pochi passi dal mare.","pl":"Świeże mleko, sardyńskie składniki i dużo cierpliwości. Nasze lody powstają codziennie w pracowni, kilka kroków od morza.","en":"Fresh milk, Sardinian ingredients and plenty of patience. Our gelato is made every day in the workshop, a few steps from the sea.","es":"Leche fresca, ingredientes sardos y mucha paciencia. Nuestro helado nace cada día en el obrador, a pocos pasos del mar.","de":"Frische Milch, sardische Zutaten und viel Geduld. Unser Eis entsteht jeden Tag in der Werkstatt, nur wenige Schritte vom Meer.","fr":"Du lait frais, des ingrédients sardes et beaucoup de patience. Notre glace est fabriquée chaque jour à l''atelier, à deux pas de la mer."},"lab_point_1":{"it":"Latte fresco","pl":"Świeże mleko","en":"Fresh milk","es":"Leche fresca","de":"Frische Milch","fr":"Lait frais"},"lab_point_2":{"it":"Ingredienti sardi","pl":"Sardyńskie składniki","en":"Sardinian ingredients","es":"Ingredientes sardos","de":"Sardische Zutaten","fr":"Ingrédients sardes"},"lab_point_3":{"it":"Fatto ogni giorno","pl":"Robione codziennie","en":"Made every day","es":"Hecho cada día","de":"Jeden Tag frisch","fr":"Fait chaque jour"},"prices_title":{"it":"Altre delizie","pl":"Inne pyszności","en":"More treats","es":"Más delicias","de":"Noch mehr Leckeres","fr":"Autres délices"},"treats_subtitle":{"it":"Non solo coni: anche queste, fatte al momento.","pl":"Nie tylko rożki: to też robimy na miejscu.","en":"Not just cones: these are made to order too.","es":"No solo cucuruchos: también esto, al momento.","de":"Nicht nur Waffeln: das gibt es auch, frisch gemacht.","fr":"Pas que des cornets : ceux-ci aussi, préparés minute."},"reviews_title":{"it":"Dicono di noi","pl":"Co o nas mówią","en":"What people say","es":"Lo que dicen de nosotros","de":"Was Gäste sagen","fr":"Ce qu''on dit de nous"},"visit_title":{"it":"Vieni a trovarci","pl":"Odwiedź nas","en":"Come and see us","es":"Ven a vernos","de":"Besuch uns","fr":"Viens nous voir"},"visit_body":{"it":"In Via Amsicora, nel centro di Santa Teresa Gallura. Da mercoledì a domenica.","pl":"Via Amsicora, w centrum Santa Teresa Gallura. Od środy do niedzieli.","en":"On Via Amsicora, in the centre of Santa Teresa Gallura. Wednesday to Sunday.","es":"En la Via Amsicora, en el centro de Santa Teresa Gallura. De miércoles a domingo.","de":"In der Via Amsicora, im Zentrum von Santa Teresa Gallura. Mittwoch bis Sonntag.","fr":"Via Amsicora, au centre de Santa Teresa Gallura. Du mercredi au dimanche."},"marquee":{"it":"Gelato artigianale · Fatto ogni giorno · Santa Teresa Gallura","pl":"Lody rzemieślnicze · Robione codziennie · Santa Teresa Gallura","en":"Artisan gelato · Made every day · Santa Teresa Gallura","es":"Helado artesanal · Hecho cada día · Santa Teresa Gallura","de":"Handwerkliches Eis · Jeden Tag frisch · Santa Teresa Gallura","fr":"Glace artisanale · Faite chaque jour · Santa Teresa Gallura"},"footer_text":{"it":"Gelato artigianale, fatto ogni giorno.","pl":"Lody rzemieślnicze, robione codziennie.","en":"Artisan gelato, made every day.","es":"Helado artesanal, hecho cada día.","de":"Handwerkliches Eis, jeden Tag frisch.","fr":"Glace artisanale, faite chaque jour."}}'::jsonb, '+39 348 609 3847', 'Via Amsicora 2, 07028 Santa Teresa Gallura (OT)', 'https://www.google.com/maps/place/Gelateria+Onda+La+Gelateria+Artigianale/@41.2425982,9.1903055,17z', 41.2425982, 9.1903055, '{"facebook":"https://www.facebook.com/lagelateriartigianale"}'::jsonb, 4.6, 810, 'https://www.google.com/maps/place/Gelateria+Onda+La+Gelateria+Artigianale/@41.2425982,9.1903055,17z', null, 4.6, null, 'https://www.tripadvisor.com/Search?q=Gelateria%20Onda%20Santa%20Teresa%20Gallura', '{}'::jsonb, '{"intensity":1,"preloader":"full","smoothScroll":true,"cursor":true,"sprinkles":true,"galleryInterval":4.5,"meltSpeed":1}'::jsonb, 'Europe/Rome')
